$ErrorActionPreference="Stop"
$ProjectRoot=Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $ProjectRoot
$files=@{
  "src/views/Home.vue"=""
  "src/components/CategoryCarousel.vue"=""
  "src/components/VideoCarousel.vue"=""
  "src/views/Products.vue"=""
  "src/assets/styles/latest-ui.css"=""
}
foreach($relativePath in $files.Keys){$fullPath=Join-Path $ProjectRoot $relativePath;$dir=Split-Path -Parent $fullPath;if(!(Test-Path $dir)){New-Item -ItemType Directory -Path $dir -Force|Out-Null};[IO.File]::WriteAllBytes($fullPath,[Convert]::FromBase64String($files[$relativePath]));Write-Host "Updated $relativePath"}
$css=Join-Path $ProjectRoot "src\assets\styles\main.css";$extra=Get-Content (Join-Path $ProjectRoot "src\assets\styles\latest-ui.css") -Raw;$main=Get-Content $css -Raw;if($main -notmatch "\.carousel-row"){[IO.File]::WriteAllText($css,$main+"`r`n`r`n"+$extra,[Text.UTF8Encoding]::new($false))};Remove-Item (Join-Path $ProjectRoot "src\assets\styles\latest-ui.css") -Force
Write-Host "";Write-Host "Mother Soil latest UI updates applied successfully." -ForegroundColor Green